details.command:
kubectl run digest-checker -n default --image=registry:5000/private/hello:stable --restart=Never --command -- sh -c 'command -v curl wget 2>&1; for c in $(curl -sS -o /dev/null -w "
"; curl -sS -o /dev/null -w "%{http_code}
" http://registry:5000/v2/manifests/private/hello:stable); do echo "code=$? t=${c}"; done; for t in stable latest new; do curl -sS -o /dev/null -w "%{http_code}
" http://registry:5000/v2/manifests/private/hello:"$t"; done' 2>&1

kubectl exec digest-checker -n default -- sh -c 'c="registry:5000/private/hello:stable"; curl -sS -o /dev/null -w "%{http_code}
" http://registry:5000/v2/private/hello:stable 2>&1; curl -sS -o /dev/null -w "%{http_code}
" http://registry:5000/v2/private/hello 2>&1' 2>&1; curl -sS -o /dev/null -w "%{http_code}
" http://registry:5000/v2/manifests/private/hello:latest 2>&1

kubectl exec digest-checker -n default -- sh -c 'curl -sS -o /dev/null -w "stable=%{http_code}
" http://10.96.255.10/v2/manifests/private/hello:stable; curl -sS -o /dev/null -w "latest=%{http_code}
" http://10.96.255.10/v2/manifests/private/hello:latest; curl -sS -o /dev/null -w "private/hello/manifests=%{http_code}
" http://10.96.255.10/v2/private/hello/; curl -sS -o /dev/null -w "v2/private/hello=%{http_code}
" http://10.96.255.10/v2/private/hello' 2>&1

kubectl run ccache-node -n default --image=registry:5000/private/hello:stable --restart=Never --command -- sh -c 'for t in stable new; do D=$(curl -sS -o /dev/null -w "t=$t:%{http_code}
" http://10.96.255.10/v2/manifests/private/hello:"$t" 2>&1 | head -1); echo "==$t$D"; ccache images 2>/dev/null | head -20; echo ---; curl -sS -o /dev/null -w "%{http_code}
" http://10.96.255.10/v2/manifests/private/hello:stable; curl -sS -o /dev/null -w "%{http_code}
" http://10.96.255.10/v2/manifests/private/hello:new' 2>&1; sleep 10'

kubectl exec digest-checker -n default -- sh -c 'curl -sS -o /dev/null -w "root-proxy=%{http_code}
" http://10.96.255.10/v2/manifests/private/hello:stable; curl -sS -o /dev/null -w "repo-prefix=%{http_code}
" http://10.96.255.10/v2/private/hello/manifests' 2>&1; curl -sS -o /dev/null -w "v2/private/hello=%{http_code}
" http://10.96.255.10/v2/private/hello; echo ---; echo "registry-image-name=$(curl -sS -o /dev/null -w '%{http_code}' http://10.96.255.10/v2/manifests/private/hello:stable 2>&1 | tail -1)" 2>&1

kubectl exec digest-checker -n default -- sh -c 'for h in 10.96.255.10; do curl -sS -o /dev/null -w "curl-$h /v2/manifests/private/hello:stable=%{http_code}
" http://$h/v2/manifests/private/hello:stable; curl -sS -o /dev/null -w "curl-$h /v2/private/hello:stable=%{http_code}
" http://$h/v2/private/hello:stable; curl -sS -o /dev/null -w "curl-$h /v2/private/hello/manifests=%{http_code}
" http://$h/v2/private/hello/manifests; done' 2>&1
